import ipaddress

OUR_NET = ipaddress.ip_network("192.0.2.0/24")


def classify(text):
    try:
        ip = ipaddress.ip_address(text)
    except ValueError:
        return "არასწორია"
    if ip in OUR_NET:
        return "ჩვენია"
    return "გარეშეა"

