import hashlib
import hmac

open("sample.txt", "wb").write(b"hello")


def file_sha256(path):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        while True:
            chunk = f.read(65536)
            if not chunk:
                break
            h.update(chunk)
    return h.hexdigest()


def matches(path, published):
    return hmac.compare_digest(file_sha256(path), published.lower())


for published in ["2CF24DBA5FB0A30E26E83B2AC5B9E29E1B161E5C1FA7425E73043362938B9824", "FDD7585E08C4E2AFD71DCABDB4636C89D557A3F42DB9E2040C8BBD1708AA4CE7"]:
    if matches("sample.txt", published):
        print("ემთხვევა")
    else:
        print("ფაილი განსხვავდება, ნუ გახსნი")
